from collections import Counter
def analyze(I):
    H,W=len(I),len(I[0])
    cnt=Counter(x for r in I for x in r)
    sep=None
    for c in range(W):
        v=[I[r][c] for r in range(H)]
        if len(set(v))==1 and v[0]!=cnt.most_common(1)[0][0]:
            sep=c; break
    return sep,cnt
